body:
`checkEnvAccess` uses `config.process` to decide whether environment variable access is configured, but the schema in `plugin-security-advanced.zod.ts` exposes environment controls under `config.environment`, not `config.process`. As a result, sandbox environment settings are ignored and env access may be incorrectly allowed or denied; this logic should be updated to respect `config.environment` (including its `mode` and allow/deny lists) to correctly enforce sandbox policies.
```suggestion
    // Environment configuration is defined under `config.environment` in the
    // plugin security schema. Use a loose type here to avoid coupling this
    // runtime to the exact schema shape while still enforcing policy.
    const envConfig: any = (config as any).environment;

    if (!envConfig) {
      return { allowed: false, reason: 'Environment access not configured' };
    }

    const mode: string | undefined =
      typeof envConfig.mode === 'string' ? envConfig.mode : undefined;

    // Support common allow/deny property names to stay compatible with the
    // schema without depending on its exact TypeScript type here.
    const allowList: string[] =
      Array.isArray(envConfig.allow)
        ? envConfig.allow
        : Array.isArray(envConfig.allowList)
          ? envConfig.allowList
          : [];

    const denyList: string[] =
      Array.isArray(envConfig.deny)
        ? envConfig.deny
        : Array.isArray(envConfig.denyList)
          ? envConfig.denyList
          : [];

    // If no variable specified, check general environment access based on mode.
    if (!varName) {
      if (mode && ['disabled', 'none', 'deny_all'].includes(mode)) {
        return {
          allowed: false,
          reason: 'Environment access disabled by sandbox policy',
        };
      }

      // For any other mode (including undefined), allow general access.
      return { allowed: true };
    }

    // Variable-specific checks based on mode and allow/deny lists.
    if (mode && ['allow', 'allowlist', 'whitelist'].includes(mode)) {
      if (allowList.includes(varName)) {
        return { allowed: true };
      }

      return {
        allowed: false,
        reason: `Access to environment variable "${varName}" not allowed by sandbox policy`,
      };
    }

    if (mode && ['deny', 'denylist', 'blacklist'].includes(mode)) {
      if (denyList.includes(varName)) {
        return {
          allowed: false,
          reason: `Access to environment variable "${varName}" denied by sandbox policy`,
        };
      }

      return { allowed: true };
    }

    if (mode && ['disabled', 'none', 'deny_all'].includes(mode)) {
      return {
        allowed: false,
        reason: `Environment access disabled by sandbox policy`,
      };
    }

    // Default: if environment access is configured but mode is unrecognized,
    // remain permissive and allow access (matching previous behavior when
    // configuration existed).
```
